            cols.extend(x[:,k]*x[:,l] for k,l in itertools.combinations(range(4),2))
        D=np.column_stack(cols); a=np.linalg.lstsq(D,y[:,j],rcond=None)[0]; coefficients.append(a); train.append(np.std(D@a-y[:,j]));
